// Turns match events and on-court "moments" into party prompts.

import { MatchEvent, MatchState, Team, other } from './scoring';
import { Spice, renderPenalty } from './spice';

/** Sound effects in assets/sounds (generated by scripts/make_sounds.py). */
export type SoundId = 'airhorn' | 'fanfare' | 'sadtrombone' | 'ding' | 'buzzer' | 'whoosh' | 'drumroll' | 'zap';

export interface PartyPrompt {
  emoji: string;
  title: string;
  body: string;
  /** Big moments get a full-screen takeover instead of a toast. */
  big?: boolean;
  sound?: SoundId;
}

export type MomentId = 'net' | 'ace' | 'kitchen' | 'erne' | 'longRally' | 'bodyShot' | 'wayOut';

export interface Moment {
  id: MomentId;
  emoji: string;
  label: string;
  /** Asked before the prompt: which team did it? */
  ask: string;
  /** Every moment ends the rally: does the team that did it win it, or lose it? */
  rallyGoesTo: 'doer' | 'other';
}

export const MOMENTS: Moment[] = [
  { id: 'net', emoji: '🥅', label: 'Into the net', ask: 'Who hit the net?', rallyGoesTo: 'other' },
  { id: 'ace', emoji: '⚡', label: 'Ace', ask: 'Who served the ace?', rallyGoesTo: 'doer' },
  { id: 'kitchen', emoji: '🍳', label: 'Kitchen fault', ask: 'Who faulted?', rallyGoesTo: 'other' },
  { id: 'erne', emoji: '🦅', label: 'Erne / ATP', ask: 'Who hit it?', rallyGoesTo: 'doer' },
  { id: 'longRally', emoji: '🔁', label: '10+ rally', ask: 'Who won the rally?', rallyGoesTo: 'doer' },
  { id: 'bodyShot', emoji: '🎯', label: 'Body shot', ask: 'Who hit the body shot?', rallyGoesTo: 'doer' },
  { id: 'wayOut', emoji: '🚀', label: 'Way out', ask: 'Who hit it out?', rallyGoesTo: 'other' },
];

/** The team that wins the rally when `doer` caused this moment. */
export function momentRallyWinner(id: MomentId, doer: Team): Team {
  return MOMENTS.find((m) => m.id === id)!.rallyGoesTo === 'doer' ? doer : other(doer);
}

// {who} is the team that did it, {them} the other team.
const MOMENT_TEXT: Record<MomentId, { title: string; body: string; sound: SoundId }> = {
  net: { title: 'Net Tax', body: '{who} fed the net. Net tax: {who}, {sips:1}.', sound: 'sadtrombone' },
  ace: { title: 'Ace!', body: '{who} aced {them}. {them}, {sips:1}.', sound: 'zap' },
  kitchen: { title: 'Kitchen Fault', body: 'Get out of the kitchen! {who}, {sips:1}.', sound: 'buzzer' },
  erne: { title: 'Highlight Reel', body: 'Legendary shot by {who}! {them}, {sips:3}.', sound: 'airhorn' },
  longRally: { title: 'Dink War', body: '{who} won a movie of a rally. {them}, {sips:1}. Everyone else too.', sound: 'fanfare' },
  bodyShot: { title: 'Body Shot', body: '{who} tagged {them}. Payback: {who}, {sips:1}.', sound: 'zap' },
  wayOut: { title: 'Launched It', body: 'That ball is in orbit. {who}, {sips:2}.', sound: 'whoosh' },
};

const fill = (text: string, vars: Record<string, string>, spice: Spice, rng: () => number) =>
  renderPenalty(
    text.replace(/\{(\w+)\}/g, (m, key: string) => vars[key] ?? m),
    spice,
    rng,
  );

export function momentPrompt(
  id: MomentId,
  who: string,
  spice: Spice,
  them = 'the other team',
  rng: () => number = Math.random,
): PartyPrompt {
  const moment = MOMENTS.find((m) => m.id === id)!;
  const t = MOMENT_TEXT[id];
  return { emoji: moment.emoji, title: t.title, body: fill(t.body, { who, them }, spice, rng), sound: t.sound };
}

/**
 * Pick at most one prompt for a rally's events. Rarer, bigger events win.
 * Side-outs only trigger sometimes so the game doesn't stop every rally.
 */
export function promptForEvents(
  events: MatchEvent[],
  state: MatchState,
  spice: Spice,
  rng: () => number = Math.random,
): PartyPrompt | null {
  const name = (t: Team) => state.config.teamNames[t];
  const f = (text: string, vars: Record<string, string> = {}) => fill(text, vars, spice, rng);

  const over = events.find((e) => e.type === 'gameOver');
  if (over && over.type === 'gameOver') {
    const loser = name(other(over.winner));
    if (over.pickled) {
      return {
        emoji: '🥒',
        title: 'PICKLED!',
        body: f('{loser} got skunked. Pickle Penalty: {loser}, {finish}. Then a lap of shame.', { loser }),
        big: true,
        sound: 'airhorn',
      };
    }
    return {
      emoji: '🏆',
      title: `${name(over.winner)} wins!`,
      body: f('{loser}, {sips:2}. {winner} pick the next house rule.', { loser, winner: name(over.winner) }),
      big: true,
      sound: 'fanfare',
    };
  }

  const watch = events.find((e) => e.type === 'pickleWatch');
  if (watch && watch.type === 'pickleWatch') {
    return {
      emoji: '👀',
      title: 'Pickle Watch',
      body: f('{team} has zero points. Score one now or face the Pickle Penalty.', { team: name(watch.team) }),
      sound: 'drumroll',
    };
  }

  const streak = events.find((e) => e.type === 'streak');
  if (streak && streak.type === 'streak') {
    return {
      emoji: '🔥',
      title: `${streak.length}-point heater`,
      body: f(`{team} is cooking. {victims} must {sips:${Math.min(streak.length / 2, 3)}}.`, {
        team: name(streak.team),
        victims: name(other(streak.team)),
      }),
      sound: 'whoosh',
    };
  }

  const gamePoint = events.find((e) => e.type === 'gamePoint');
  if (gamePoint && gamePoint.type === 'gamePoint') {
    return {
      emoji: '⏳',
      title: 'Game Point',
      body: f('{team} is one away. {other} — {sips:1} for courage.', {
        team: name(gamePoint.team),
        other: name(other(gamePoint.team)),
      }),
      sound: 'drumroll',
    };
  }

  const tied = events.find((e) => e.type === 'tied');
  if (tied && tied.type === 'tied') {
    return {
      emoji: '🤝',
      title: `Tied at ${tied.score}`,
      body: f('Dead even. {a} and {b}, everybody {sips:1}.', { a: name(0), b: name(1) }),
      sound: 'ding',
    };
  }

  const sideOut = events.find((e) => e.type === 'sideOut');
  if (sideOut && sideOut.type === 'sideOut' && rng() < 0.25) {
    return {
      emoji: '🔄',
      title: 'Side Out',
      body: f("{team} lost the serve. {team}'s server, {sips:1}.", { team: name(other(sideOut.to)) }),
      sound: 'ding',
    };
  }

  return null;
}
